package com.hau.notification.infrastructure.rabbitmq;import com.hau.notification.application.dto.IncomingEvent;import com.hau.notification.application.port.in.EventNotificationUseCase;import com.rabbitmq.client.Channel;import org.slf4j.*;import org.springframework.amqp.core.Message;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.stereotype.Component;import java.io.IOException;import java.util.*;
@Component public class DomainEventConsumer{private static final Logger log=LoggerFactory.getLogger(DomainEventConsumer.class);private final EventNotificationUseCase useCase;private final RabbitTemplate template;public DomainEventConsumer(EventNotificationUseCase u,RabbitTemplate t){useCase=u;template=t;}@RabbitListener(queues=RabbitConfiguration.QUEUE)public void consume(EventEnvelope e,Message m,Channel c)throws IOException{long tag=m.getMessageProperties().getDeliveryTag();try{if(e==null||e.eventId()==null||e.eventType()==null)throw new IllegalArgumentException("Invalid event");useCase.handle(new IncomingEvent(e.eventId(),e.eventType(),e.correlationId(),e.payload()));c.basicAck(tag,false);}catch(Exception x){long attempt=attempts(m)+1;log.warn("Notification event failed; eventId={}, attempt={}",e==null?null:e.eventId(),attempt);if(attempt>=3){template.send(RabbitConfiguration.DLX,"dead",m);c.basicAck(tag,false);}else c.basicNack(tag,false,false);}}private long attempts(Message m){List<Map<String,?>> d=m.getMessageProperties().getXDeathHeader();if(d==null||d.isEmpty())return 0;Object n=d.getFirst().get("count");return n instanceof Number x?x.longValue():0;}}
